var factory = new ConnectionFactory() { HostName = "localhost" };
using var connection = factory.CreateConnection();
using var channel = connection.CreateModel();

channel.ExchangeDeclare("order.events", ExchangeType.Topic, durable: true);

// Durable: survives broker restarts; non-exclusive: multiple consumers allowed
channel.QueueDeclare(
    queue: "order-processing-queue",
    durable: true,
    exclusive: false,
    autoDelete: false);

channel.QueueBind("order-processing-queue", "order.events", "order.#");

// Messages published before this consumer starts will be redelivered
channel.BasicQos(prefetchSize: 0, prefetchCount: 10, global: false);
channel.BasicConsume(
    queue: "order-processing-queue",
    autoAck: false,
    consumer: new EventingBasicConsumer(channel));

const amqp = require('amqplib');

async function transientSubscriber() {
  const conn = await amqp.connect('amqp://localhost');
  const ch = await conn.createChannel();

  await ch.assertExchange('order.events', 'topic', { durable: true });

  // exclusive + auto-delete = transient subscription
  const { queue } = await ch.assertQueue('', { exclusive: true });
  await ch.bindQueue(queue, 'order.events', 'order.#');

  ch.consume(queue, (msg) => {
    if (msg.content) {
      console.log('Transient consumer received:', msg.content.toString());
    }
  }, { noAck: true });

  console.log('Transient subscriber active on queue:', queue);

  // After this function exits and connection closes, queue is deleted
}

transientSubscriber();
